//! Key side: the [`KeyEncode`] trait and [`PrefixKey`].
//!
//! A key struct derived with `#[derive(KeyEncode)]` **is** the DDL: SQL
//! defines collection structure, the Rust struct defines key encoding, and the
//! compiler enforces format consistency. Fields are big-endian, fixed
//! width, no separators — decoding is pure pointer slicing.

use crate::model::field::{FieldDesc, FieldType};

/// Fixed-width key encoding contract.
///
/// `KEY_LEN` / `FIELD_WIDTHS` / `encode` are generated by
/// `#[derive(KeyEncode)]`; `encode_prefix_named` is the "truncated
/// identity" primitive: encode the first N fields in declaration order.
pub trait KeyEncode: Sized + Clone {
    /// Total encoded byte count (payload only, namespace header excluded).
    const KEY_LEN: usize;
    /// Field name → width table (declaration order). The edge macro uses it
    /// to validate at runtime that `ok_head` names a legal declaration-order
    /// prefix.
    const FIELD_WIDTHS: &'static [(&'static str, usize)];
    fn encode(&self) -> Vec<u8>;
    /// Append the bytes [`encode`](Self::encode) would return to `buf`, without
    /// materialising them.
    ///
    /// The default is correct for any impl (it copies the encoded Vec in), and
    /// the derive overrides it with the field writers themselves. It exists
    /// because every caller that wants a key's bytes is about to copy them into
    /// a buffer it already owns — an index entry, a scan prefix — and a
    /// key-sized Vec per entry is an allocation serving nothing.
    fn encode_into(&self, buf: &mut Vec<u8>) {
        buf.extend_from_slice(&self.encode());
    }
    fn decode(bytes: &[u8]) -> Self;
    /// Field descriptors, declaration order — the key's single field list
    /// with primitive kinds (Arrow schema / column builders, ADR-0007).
    const FIELDS: &'static [crate::model::field::FieldDesc] = &[];
    /// Encode the first `names.len()` fields in declaration order;
    /// `names` must be a declaration-order prefix (first mismatch panics).
    fn encode_prefix_named(&self, buf: &mut Vec<u8>, names: &[&str]) -> usize;
    /// Width of the corresponding prefix.
    fn prefix_width(names: &[&str]) -> usize;

    /// Append the named fields' bytes in REQUEST order — the key-order face's
    /// sort segment (ADR-0054).
    ///
    /// Unlike [`encode_prefix_named`](Self::encode_prefix_named) the names need
    /// not be a declaration-order prefix: a lead face orders a collection by one
    /// of its identities, and that identity's field order is a permutation of
    /// the declaration (`[channel][member]` scanned as `[member]`). A name the
    /// key does not declare writes nothing; the derive's const check makes that
    /// unreachable from a declaration. Returns the bytes written.
    fn encode_field_named(&self, buf: &mut Vec<u8>, names: &[&str]) -> usize {
        let full = self.encode();
        let mut written = 0usize;
        for n in names {
            let mut off = 0usize;
            for f in Self::FIELDS {
                if f.name == *n {
                    buf.extend_from_slice(&full[off..off + f.width]);
                    written += f.width;
                    break;
                }
                off += f.width;
            }
        }
        written
    }

    /// Width of the same segment, without encoding it.
    fn field_width_named(names: &[&str]) -> usize {
        let mut total = 0usize;
        for n in names {
            for f in Self::FIELDS {
                if f.name == *n {
                    total += f.width;
                    break;
                }
            }
        }
        total
    }
}

/// A value that can lead a key-order face's segment (ADR-0054).
///
/// The point of the trait is the [`KIND`](Self::KIND)/[`WIDTH`](Self::WIDTH)
/// pair: a lead declaration names a KEY field, and the document derive cannot
/// see that type's fields, so the generated probe step checks the argument it
/// was handed against the key's own `FIELDS` table at compile time instead of
/// taking a concrete parameter type. Sealed: the set of values a key can hold is
/// the key codec's, not an extension point.
pub trait KeyFieldValue: key_field_value_sealed::Sealed {
    /// The `FieldType` this value encodes as. A parametric kind (`Vocab`) is
    /// compared by family, not by payload — see [`kind_matches`].
    const KIND: FieldType;
    /// Encoded width in bytes, big-endian on the wire.
    const WIDTH: usize;
    /// Append the value's identity bytes.
    fn write_be(&self, buf: &mut Vec<u8>);
}

mod key_field_value_sealed {
    pub trait Sealed {}
}

macro_rules! key_field_ints {
    ($($t:ty => $kind:ident),* $(,)?) => {$(
        impl key_field_value_sealed::Sealed for $t {}
        impl KeyFieldValue for $t {
            const KIND: FieldType = FieldType::$kind;
            const WIDTH: usize = ::core::mem::size_of::<$t>();
            fn write_be(&self, buf: &mut Vec<u8>) {
                buf.extend_from_slice(&self.to_be_bytes());
            }
        }
    )*};
}
key_field_ints!(u8 => U8, u16 => U16, u32 => U32, u64 => U64);

impl<const N: usize> key_field_value_sealed::Sealed for [u8; N] {}
impl<const N: usize> KeyFieldValue for [u8; N] {
    const KIND: FieldType = FieldType::FixedBytes;
    const WIDTH: usize = N;
    fn write_be(&self, buf: &mut Vec<u8>) {
        buf.extend_from_slice(self);
    }
}

impl key_field_value_sealed::Sealed for crate::model::wrappers::uuid::Uuid4 {}
impl KeyFieldValue for crate::model::wrappers::uuid::Uuid4 {
    const KIND: FieldType = FieldType::Uuid4;
    const WIDTH: usize = 16;
    fn write_be(&self, buf: &mut Vec<u8>) {
        buf.extend_from_slice(self.as_bytes());
    }
}

impl key_field_value_sealed::Sealed for crate::model::wrappers::uuid::Uuid7 {}
impl KeyFieldValue for crate::model::wrappers::uuid::Uuid7 {
    const KIND: FieldType = FieldType::Uuid7;
    const WIDTH: usize = 16;
    fn write_be(&self, buf: &mut Vec<u8>) {
        buf.extend_from_slice(self.as_bytes());
    }
}

impl<N: okm_value::Id> key_field_value_sealed::Sealed
    for crate::model::vocab::Vocab<N>
{
}
impl<N: okm_value::Id> KeyFieldValue for crate::model::vocab::Vocab<N> {
    /// The family, not the field: a `Vocab`'s `FieldType` payload is the
    /// declaration's id face, which the document side does not know.
    const KIND: FieldType = FieldType::Vocab(0);
    const WIDTH: usize = N::WIDTH;
    fn write_be(&self, buf: &mut Vec<u8>) {
        let img = self.wire16();
        buf.extend_from_slice(&img[16 - N::WIDTH..]);
    }
}

/// Do two `FieldType`s name the same KIND? Parametric kinds compare by family —
/// the payload (`Vocab`'s id face) is a declaration detail, not a wire kind.
pub const fn kind_matches(a: FieldType, b: FieldType) -> bool {
    matches!(
        (a, b),
        (FieldType::U8, FieldType::U8)
            | (FieldType::U16, FieldType::U16)
            | (FieldType::U32, FieldType::U32)
            | (FieldType::U64, FieldType::U64)
            | (FieldType::FixedBytes, FieldType::FixedBytes)
            | (FieldType::Uuid4, FieldType::Uuid4)
            | (FieldType::Uuid7, FieldType::Uuid7)
            | (FieldType::Vocab(_), FieldType::Vocab(_))
    )
}

/// Compile-time answer to "is `name` one of this key's fields, and do `kind` /
/// `width` agree with what the key declares?" (ADR-0054).
///
/// A proc macro cannot resolve another type's fields, so a lead declaration is
/// checked where the compiler can see both sides: inside a generated `const`
/// block, against `<Key as KeyEncode>::FIELDS`. The failure is a const-eval
/// error at the use site rather than an expansion-time `syn::Error` — the one
/// diagnostic cost the split declaration pays.
pub const fn key_field_matches(
    fields: &'static [FieldDesc],
    name: &str,
    kind: FieldType,
    width: usize,
) -> bool {
    let mut i = 0usize;
    while i < fields.len() {
        if str_eq(fields[i].name, name) {
            return kind_matches(fields[i].ty, kind) && fields[i].width == width;
        }
        i += 1;
    }
    false
}

/// Compile-time answer to "is `name` one of this key's fields?" (ADR-0054).
///
/// The declaration-level half of the check: a lead declaration's field list must
/// name key fields, and a name the key does not declare would otherwise write an
/// empty segment — silent, and only visible as entries ordered by their tails.
/// The value's kind and width are checked separately, per probe step, because
/// only the call site knows the type.
pub const fn key_field_exists(fields: &'static [FieldDesc], name: &str) -> bool {
    let mut i = 0usize;
    while i < fields.len() {
        if str_eq(fields[i].name, name) {
            return true;
        }
        i += 1;
    }
    false
}

/// `str` equality in a `const` context (`==` on `str` is not const).
const fn str_eq(a: &str, b: &str) -> bool {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    if a.len() != b.len() {
        return false;
    }
    let mut i = 0usize;
    while i < a.len() {
        if a[i] != b[i] {
            return false;
        }
        i += 1;
    }
    true
}

/// Decode product of a truncated identity: the full `A` decode plus the
/// number of bytes consumed by the identity prefix.
///
/// Prefix fields are trustworthy; trailing fields are garbage read past the
/// boundary into B's encoding region — callers must use only the prefix
/// fields, or take `decoded`'s prefix portion to scan the main collection.
pub struct PrefixKey<A> {
    pub decoded: A,
    /// Bytes consumed by the identity prefix (= sum of `ok_head` field widths).
    pub taken: usize,
}
